const sourceKeys={chaos:['creation'],emptiness:['value'],flux:['order'],generation:['inner','value'],probability:['probability'],alltime:['probability'],emotion:['emotion']};
export function deepeningSources(id){return (sourceKeys[id]||[]).map(key=>{const [label,url,note]=sources[key];return `<p><a class="source-link" href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a><br>${note}</p>`;}).join('');}
export function withEmotionQuestions(id,content){const extra=(emotionDeepening[id]||[]).map(([q,ps])=>`<details class="action-fold deep-reading"><summary>${q}</summary><div class="action-prose">${ps.map(p=>`<p>${p}</p>`).join('')}</div></details>`).join('');if(!extra)return content;const end=content.lastIndexOf('<button type="button" class="action-cite"');return end<0?content+extra:content.slice(0,end)+extra+content.slice(end);}
